changes.before:
mark('decode packaged hunter portrait');
evidence.portrait = await page.locator('.title-hunter').evaluate(async element => {
  const match = getComputedStyle(element).backgroundImage.match(/^url\(["']?(.*?)["']?\)$/);
  if (!match) throw new Error('Hunter portrait background URL absent');
  const image = new Image(); image.src = match[1]; await image.decode();
  return {width: image.naturalWidth, height: image.naturalHeight, protocol: new URL(image.src).protocol};
});
assert.deepEqual(evidence.portrait, {width: 1199, height: 1312, protocol: 'file:'});

changes.after:
mark('decode actual packaged hunt-entry hunter sheet');
const titleArt = page.locator('#scene-ui .hunt-entry-art');
await expect(titleArt).toBeVisible();
await expect(page.locator('#scene-ui [data-ui="new"]')).toBeVisible();
evidence.portrait = await titleArt.evaluate(async element => {
  const style = getComputedStyle(element);
  const match = style.backgroundImage.match(/^url\(["']?(.*?)["']?\)$/);
  if (!match) throw new Error('Hunt-entry hunter background URL absent');
  const image = new Image(); image.src = match[1]; await image.decode();
  return {width: image.naturalWidth, height: image.naturalHeight, protocol: new URL(image.src).protocol,
    url: image.src, backgroundSize: style.backgroundSize, backgroundPosition: style.backgroundPosition};
});
assert.deepEqual({width: evidence.portrait.width, height: evidence.portrait.height, protocol: evidence.portrait.protocol},
  {width: 1536, height: 1024, protocol: 'file:'});
assert.ok(new URL(evidence.portrait.url).pathname.endsWith('/dist/art/hunter-marek-v07-r3.png'),
  'Title hunter URL escaped the actual packaged sheet');
assert.equal(evidence.portrait.backgroundSize, '300% 200%');
assert.equal(evidence.portrait.backgroundPosition, '0% 0%');

